def bubble_sort_asc(arr):
    result = arr[:]

    for pass_index in range(len(result)):
        for i in range(0, len(result) - pass_index - 1):
            if result[i] > result[i + 1]:
                result[i], result[i + 1] = result[i + 1], result[i]

    return result

print(bubble_sort_asc([5, 2, 8, 1]))

